def caesar_cipher(text: str, shift: int) -> str:
    """
    Apply a Caesar cipher to the input text.
    Only shift letters within the range of 'a' to 'z' and 'A' to 'Z'.
    Leave other characters unchanged.
    """
    result = ""
    for char in text:
        if char.isalpha():
            # Shift character if it's within 'a' to 'z' and 'A' to 'Z'
            if char.isupper():
                result += chr(((ord(char) - ord('A')) + shift) % 26)
            else:
                result += chr(((ord(char) - ord('a')) + shift) % 26) + ord('A'))
        else:
            result += char
    return result
```

